#!/usr/bin/env bash
# Fogwarden relay installer for Ubuntu 22.04/24.04, generated by Fogwarden.
# Run as root next to relay.mjs and fogwarden-relay.nginx.conf. Re-runs keep
# the DM key; they rewrite the nginx site and certbot reinstalls the
# existing certificate into it. On a server run by nginx-manager the relay
# registers a site spec there instead, so the manager keeps owning nginx.
set -euo pipefail

DOMAIN='@DOMAIN@'
EMAIL='@EMAIL@'
PORT='@PORT@'

# The app pipes the sudo password on stdin; nothing below may read leftovers
# or wait for an answer.
exec </dev/null

if [[ $(id -u) -ne 0 ]]; then
  echo "install.sh must run as root: sudo bash install.sh" >&2
  exit 1
fi

cd "$(dirname "$0")"
for file in relay.mjs fogwarden-relay.nginx.conf; do
  if [[ ! -f $file ]]; then
    echo "$file must be next to install.sh" >&2
    exit 1
  fi
done

export DEBIAN_FRONTEND=noninteractive

MANAGED=false
if command -v nginx-manager >/dev/null; then
  MANAGED=true
fi
SPEC_FILE=/etc/fogwarden-relay/fogwarden-relay.site.env
CERT_DIR=/etc/letsencrypt/live/$DOMAIN

# The relay's restart loop would fight another service for the port.
RELAY_PID=$(systemctl show -p MainPID --value fogwarden-relay.service 2>/dev/null || true)
if ss -Hltnp "sport = :$PORT" | grep -v "pid=${RELAY_PID:-0}," | grep -q .; then
  echo "Port $PORT is taken by another service; choose another relay port" >&2
  exit 1
fi

if $MANAGED; then
  echo "==> nginx-manager found: the relay gets a site spec, not an nginx site"
  install -d -o root -g root -m 0755 /etc/fogwarden-relay
  # Uploads up to 1 GiB; quiet WebSockets of a paused game stay open.
  cat >"$SPEC_FILE" <<EOF
# Nginx Manager site spec v1, generated by Fogwarden.
SITE_ID=fogwarden-relay
DOMAIN=$DOMAIN
UPSTREAM=http://127.0.0.1:$PORT
SERVICE_NAME=fogwarden-relay
ENABLE_HTTPS=true
WEBSOCKET=true
CLIENT_MAX_BODY_SIZE=1024m
PROXY_READ_TIMEOUT=1h
SECURITY_SCANNER_BLOCKS=true
EOF
  nginx-manager validate "$SPEC_FILE"
fi

echo "==> Installing packages"
apt-get update
if $MANAGED; then
  apt-get install -y curl ca-certificates
else
  apt-get install -y nginx curl ca-certificates
fi

# nginx-manager refuses a site without its certificate and serves no plain
# HTTP, so the certificate comes first, through the port 80 ACME location.
if $MANAGED && [[ ! -f $CERT_DIR/fullchain.pem ]]; then
  if [[ -z $EMAIL ]]; then
    echo "nginx-manager serves HTTPS only: give an e-mail for the certificate or put one in $CERT_DIR" >&2
    exit 1
  fi
  WEBROOT=$(nginx -T 2>/dev/null | awk '
    /location[^{]*\/\.well-known\/acme-challenge/ { acme = 1 }
    acme && $1 == "root" { sub(/;$/, "", $2); print $2; exit }')
  if [[ -z $WEBROOT ]]; then
    echo "No nginx location serves /.well-known/acme-challenge/; add one or put a certificate in $CERT_DIR" >&2
    exit 1
  fi
  echo "==> Requesting a certificate for $DOMAIN (webroot $WEBROOT)"
  apt-get install -y certbot
  certbot certonly --webroot -w "$WEBROOT" -d "$DOMAIN" --non-interactive --agree-tos -m "$EMAIL" \
    --keep-until-expiring --deploy-hook 'systemctl reload nginx'
fi

node_major() {
  node -p 'process.versions.node.split(".")[0]'
}

if ! command -v node >/dev/null || (($(node_major) < 20)); then
  echo "==> Installing Node.js 22 from NodeSource"
  curl -fsSL https://deb.nodesource.com/setup_22.x -o /tmp/nodesource_setup.sh
  bash /tmp/nodesource_setup.sh
  rm -f /tmp/nodesource_setup.sh
  apt-get install -y nodejs
fi
NODE=$(command -v node)
echo "Node.js $("$NODE" --version) at $NODE"

if ! id -u fogwarden-relay >/dev/null 2>&1; then
  echo "==> Creating system user fogwarden-relay"
  useradd --system --user-group --no-create-home --home-dir /var/lib/fogwarden-relay \
    --shell /usr/sbin/nologin fogwarden-relay
fi

echo "==> Installing relay to /opt/fogwarden-relay"
install -D -o root -g root -m 0644 relay.mjs /opt/fogwarden-relay/relay.mjs

ENV_FILE=/etc/fogwarden-relay/relay.env
install -d -o root -g root -m 0755 /etc/fogwarden-relay
DM_KEY=""
if [[ -f $ENV_FILE ]]; then
  DM_KEY=$(sed -n 's/^FOGWARDEN_DM_KEY=\([0-9a-f]\{64\}\)$/\1/p' "$ENV_FILE")
fi
if [[ -z $DM_KEY ]]; then
  echo "==> Generating the DM key"
  DM_KEY=$(od -An -tx1 -N32 /dev/urandom | tr -d ' \n')
fi
# Written aside and moved, so a failed run never leaves a half-written key.
ENV_TMP=$(mktemp /etc/fogwarden-relay/relay.env.XXXXXX)
printf 'FOGWARDEN_DM_KEY=%s\nFOGWARDEN_RELAY_PORT=%s\n' "$DM_KEY" "$PORT" >"$ENV_TMP"
chown root:fogwarden-relay "$ENV_TMP"
chmod 0640 "$ENV_TMP"
mv -f "$ENV_TMP" "$ENV_FILE"

echo "==> Installing systemd service fogwarden-relay"
cat >/etc/systemd/system/fogwarden-relay.service <<EOF
[Unit]
Description=Fogwarden relay
After=network.target

[Service]
Type=simple
User=fogwarden-relay
Group=fogwarden-relay
EnvironmentFile=$ENV_FILE
Environment=FOGWARDEN_RELAY_HOST=127.0.0.1
Environment=FOGWARDEN_RELAY_DATA=/var/lib/fogwarden-relay
StateDirectory=fogwarden-relay
StateDirectoryMode=0700
ExecStart=$NODE /opt/fogwarden-relay/relay.mjs
Restart=on-failure
RestartSec=2
NoNewPrivileges=true
ProtectSystem=strict
ProtectHome=true
PrivateTmp=true
PrivateDevices=true
ProtectKernelTunables=true
ProtectKernelModules=true
ProtectControlGroups=true
RestrictSUIDSGID=true
RestrictNamespaces=true
LockPersonality=true
RestrictAddressFamilies=AF_UNIX AF_INET AF_INET6

[Install]
WantedBy=multi-user.target
EOF
systemctl daemon-reload
systemctl enable fogwarden-relay.service
systemctl restart fogwarden-relay.service

echo "==> Waiting for the relay on port $PORT"
attempt=0
until curl -fs -o /dev/null "http://127.0.0.1:$PORT/health"; do
  attempt=$((attempt + 1))
  if ((attempt >= 30)); then
    echo "The relay did not answer on port $PORT. Last log lines:" >&2
    journalctl -u fogwarden-relay.service -n 40 --no-pager >&2
    exit 1
  fi
  sleep 1
done
echo "Relay is up"

if $MANAGED; then
  echo "==> Registering $DOMAIN with nginx-manager"
  # A site from an install before nginx-manager would serve plain HTTP.
  rm -f /etc/nginx/sites-enabled/fogwarden-relay.conf /etc/nginx/sites-available/fogwarden-relay.conf
  nginx-manager --force register "$SPEC_FILE"
  nginx-manager apply
  curl -fsk -o /dev/null --resolve "$DOMAIN:443:127.0.0.1" "https://$DOMAIN/health"
  echo "https://$DOMAIN/health answers"
else
  echo "==> Configuring nginx for $DOMAIN"
  install -m 0644 fogwarden-relay.nginx.conf /etc/nginx/sites-available/fogwarden-relay.conf
  ln -sfn /etc/nginx/sites-available/fogwarden-relay.conf /etc/nginx/sites-enabled/fogwarden-relay.conf
  nginx -t
  systemctl enable --now nginx
  systemctl reload nginx

  if [[ -n $EMAIL ]]; then
    echo "==> Requesting a certificate for $DOMAIN"
    apt-get install -y certbot python3-certbot-nginx
    certbot --nginx -d "$DOMAIN" --non-interactive --agree-tos -m "$EMAIL" --redirect --keep-until-expiring
  else
    echo "No e-mail given: skipping HTTPS; the relay is served over plain HTTP"
  fi
fi

echo "==> Done"
echo "FOGWARDEN_DM_KEY=$DM_KEY"
